let demoState={slug:'',step:0,slide:0,version:'final',choice:null,showHelp:false};
let demoAudience='全部';
const DEMO_STEPS=['看原始材料','看第一轮结果','你来找问题','这样追问修改','操作最终成品'];
function demoCard(d){const r=d.result;return `<a class="demo-card" href="#demo/${d.slug}"><div class="demo-cover cover-${r.type}"><span class="preview-kind">${d.format} · 成品预览</span>${r.type==='slides'?`<strong>${esc(r.slides[0][0])}</strong><div class="mini-slide-rule"></div><span>${r.slides.length} 页可翻阅</span>`:r.type==='chart'?`<strong>图书馆 · 45%</strong><div class="mini-bars"><i style="width:90%"></i><i style="width:60%"></i><i style="width:50%"></i></div>`:r.type==='checklist'?`<strong>周末出行清单</strong><span>☑ 证件 &nbsp; □ 充电器</span><span>□ 雨伞 &nbsp; □ 衣物</span>`:`<strong>${esc(r.title)}</strong><span>${esc(r.sections?.[0]?.[0]||r.headers?.join(' / ')||'材料、依据与修改记录')}</span><div class="mini-document-rule"></div>`}</div><div class="demo-card-content"><div class="toolbar"><span class="scene-kind">${d.audience}</span><span class="small-note">${d.minutes} 分钟 · 5 步</span></div><h3>${d.title}</h3><p>${d.subtitle}</p><span class="demo-open">进入演示，跟着做</span></div></a>`;}
function demosPage(category){demoAudience=['生活','教学','办公','大学生','股票研究','PPT','文档'].includes(category)?category:'全部';return heading('跟着例子做','选一个例子，看看从头到尾怎么做','每个例子都有材料、第一次的回答、修改过程和最后的效果。你可以边看边点。这里的对话是为教学编写的，不是产品录屏。')+`<div class="demo-intro-line"><span>01 原始材料</span><span>02 初稿</span><span>03 找问题</span><span>04 修改</span><span>05 成品</span></div><div class="toolbar"><h2>${DEMOS.length} 个完整演示</h2><a href="#templates">查找 ${SCENES.length} 个备用提问模板</a></div><div class="pill-row">${['全部','生活','教学','办公','大学生','股票研究','PPT','文档'].map(a=>`<button class="pill ${a===demoAudience?'selected':''}" data-demo-filter="${a}" aria-pressed="${a===demoAudience}">${a}</button>`).join('')}</div><div id="demo-results" class="grid three"></div>`;}
function updateDemos(){const list=DEMOS.filter(d=>demoAudience==='全部'||d.audience===demoAudience||d.format===demoAudience);$('#demo-results').innerHTML=list.map(demoCard).join('');}
function studentsPage(){return heading('大学生专区','上大学以后，哪些事情可以请 AI 帮忙？','这些例子适合非计算机专业的同学，不需要会写代码。准备课堂汇报、读不懂文献、安排小组作业时，都可以试试。')+`<div class="student-start"><div><span class="badge">先选一件正在做的作业</span><h2>先看一个课堂汇报的例子</h2><p>AI 写了一个没有出处的“80%”。我们把它找出来，再看看怎样改成一份能讲清楚的 5 分钟汇报。</p>${button('跟做课堂汇报','#demo/student-talk')}</div><div class="student-route"><strong>推荐学习顺序</strong><a href="#lesson/1">① 说清任务与老师要求</a><a href="#demo/student-reading">② 读懂材料，找到原文</a><a href="#demo/student-talk">③ 先做一页，看看哪里要改</a><a href="#demo/student-paper">④ 自己想清楚，也核对引用</a></div></div><div class="section-head"><h2>六件常见的大学学习任务</h2></div><div class="grid three">${DEMOS.filter(d=>d.audience==='大学生').map(demoCard).join('')}</div><section class="card academic-note"><h2>交作业前，先确认三件事</h2><div class="grid three"><div><h3>课程允许怎样使用？</h3><p>不同课程的要求可能不一样，先问老师哪些地方可以用 AI。需要说明时，写清楚用了它做什么。</p></div><div><h3>材料和引用真实吗？</h3><p>打开真实原文核对作者、标题、年份、页码。这里的模拟数据和研究片段不能当作真实研究证据。</p></div><div><h3>我能自己解释吗？</h3><p>让 AI 反过来问你三个理解题。不会解释的概念继续追问，直到能用自己的话讲清楚。</p></div></div>${template('请不要替我提交作业。先问清任务和课程对 AI 的要求，帮我理解材料、整理思路，并指出证据缺口。讲解后请问我三个理解题，等我回答再给反馈。引用仅用我提供并核实的真实来源，不要编造文献。')}</section>`;}
function demoPage(slug){const d=DEMOS.find(x=>x.slug===slug);if(!d)return heading('没有找到','这个演示不存在。','请从案例演示中重新选择。')+button('返回案例演示','#scenes');demoState={slug,step:0,slide:0,version:'final',choice:null,showHelp:false};return `<div class="demo-heading"><a href="#scenes">返回案例演示</a><span class="tag">${d.audience} · ${d.format} · ${d.minutes} 分钟</span></div><div class="page-heading"><h1>${d.title}</h1><p>${d.subtitle}</p></div><div class="demo-disclosure">预设教学演示 · 材料与对话均为虚构样例 · 不会调用 AI 或上传资料</div><nav class="demo-steps" aria-label="案例演示步骤">${DEMO_STEPS.map((s,i)=>`<button data-demo-step="${i}" class="${i===0?'current':''}" ${i===0?'aria-current="step"':''}><b>${i+1}</b><span>${s}</span></button>`).join('')}</nav><div id="demo-stage"></div>`;}
function plainLines(lines){return `<ul class="material-lines">${lines.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;}
function conversation(who,text){return `<div class="walk-message ${who==='你'?'learner':'assistant'}"><span>${who}</span><p>${esc(text)}</p></div>`;}
function sampleTable(headers,rows){return `<div class="table-scroll" tabindex="0" role="region" aria-label="示例数据表，可横向滚动"><table class="artifact-table"><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>i===0?`<th scope="row">${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function docSections(sections){return sections.map(([h,p])=>`<section class="paper-section"><h3>${esc(h)}</h3><p>${esc(p).replace(/\n/g,'<br>')}</p></section>`).join('');}
function sampleSlide(d,n){const s=d.result.slides[n];return `<div class="slide-canvas"><div class="slide-kicker">${esc(d.result.title)}</div><h2>${esc(s[0])}</h2><ul>${s[1].map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="slide-footer"><span>AI 生活课堂 · 教学样例</span><span>${String(n+1).padStart(2,'0')} / ${d.result.slides.length}</span></div></div>`;}
function finalArtifact(d,exporting=false){const r=d.result;let content='';
 if(r.type==='slides'){if(exporting)return r.slides.map((s,n)=>sampleSlide(d,n)+`<div class="export-note">讲者备注：${esc(s[2])}</div>`).join('');content=`${sampleSlide(d,demoState.slide)}<div class="slide-controls"><button class="btn secondary" data-slide-move="-1" ${demoState.slide===0?'disabled':''}>上一页</button><span aria-live="polite">${demoState.slide+1} / ${r.slides.length}</span><button class="btn secondary" data-slide-move="1" ${demoState.slide===r.slides.length-1?'disabled':''}>下一页</button></div><details class="speaker-notes"><summary>看看这一页怎么讲</summary><p>${esc(r.slides[demoState.slide][2])}</p></details>`;return content;}
 const title=`<div class="paper-masthead">AI 生活课堂 / 教学样例</div><h2>${esc(r.title)}</h2><p class="paper-subtitle">${esc(r.subtitle)}</p>`;
 if(r.type==='document')content=docSections(r.sections);
 if(r.type==='table')content=sampleTable(r.headers,r.rows);
 if(r.type==='finance')content=sampleTable(r.headers,r.rows)+docSections(r.sections);
 if(r.type==='checklist')content=`<div class="live-checklist">${r.items.map(x=>`<label><input type="checkbox" ${exporting?'disabled':'data-case-check'}><span>${esc(x)}</span></label>`).join('')}</div>${exporting?'':`<div class="live-count" id="case-check-count" role="status">已准备 0 / ${r.items.length} 件</div><p class="small-note">试着点击。状态仅在本次演示内保留，切换步骤或刷新会重置。</p>`}`;
 if(r.type==='chart')content=`<div class="report-chart">${r.bars.map(([label,n])=>`<div class="report-bar"><div><span>${esc(label)}</span><strong>${n} 人 · ${n/r.denominator*100}%</strong></div><div class="bar-track"><span style="width:${n/r.denominator*100}%"></span></div></div>`).join('')}</div><p class="chart-formula">核算：18 + 12 + 10 = 40；45% + 30% + 25% = 100%</p>${docSections(r.sections)}`;
 if(r.type==='evidence')content=`<div class="evidence-cards">${r.rows.map(([label,text,n])=>`<div><span>${esc(label)}</span><p>${esc(text)}</p>${exporting?`<small>依据：${esc(d.material.lines[n])}</small>`:`<button class="source-jump" data-source-line="${n}">查看原文第 ${n+1} 段</button>`}</div>`).join('')}</div>${exporting?'':'<div id="source-excerpt" class="source-excerpt" aria-live="polite">点一个依据编号，回到原文检查。</div>'}`;
 if(r.type==='board')content=`<div class="task-board">${r.tasks.map(([person,task,done,status],i)=>`<article><span class="badge">${esc(person)}</span><h3>${esc(task)}</h3><p>验收：${esc(done)}</p>${exporting?`<p>原始状态：${status}</p>`:`<label class="field">进度<select data-task-status="${i}">${['未开始','待核查','进行中','已完成'].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select></label>`}</article>`).join('')}</div>${exporting?'':'<p id="board-count" class="small-note" role="status">已完成 0 / 4 项 · 本地模拟，不会通知组员</p>'}`;
 return `<article class="paper-preview artifact-${r.type}">${title}${content}</article>`;
}
function showDemoStep(){const d=DEMOS.find(x=>x.slug===demoState.slug),n=demoState.step;if(!d||!$('#demo-stage'))return;$$('[data-demo-step]').forEach(b=>{const yes=Number(b.dataset.demoStep)===n;b.classList.toggle('current',yes);if(yes)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});let left='',right='';
 if(n===0){left=`<div class="eyebrow">先弄清任务</div><h2>这一回，要做成什么？</h2><p>${esc(d.subtitle)}</p><div class="goal-note"><strong>这个例子主要学什么</strong><p>${esc(d.takeaway)}</p></div><p>右边是这次练习的全部原始材料。先读一遍，尤其留意哪些信息没有提供。</p><button class="btn" data-demo-next>材料看完了，看第一轮</button>`;right=`<div class="workspace-caption">任务开始前 / 原始材料</div><article class="material-sheet"><span class="badge">虚构教学材料</span><h2>${esc(d.material.title)}</h2>${plainLines(d.material.lines)}<p class="small-note">示例不能作为真实人物、活动、调查、财报或文献的证据。</p></article>`;}
 if(n===1){left=`<div class="eyebrow">第一次回答 · 还没检查</div><h2>回答很顺，但先别急着用。</h2>${conversation('你',d.ask)}${conversation('AI 示例',d.reply)}<p>看看右边的初稿，再回想原始材料。下一步由你找出最需要改的问题。</p><button class="btn" data-demo-next>我来找问题</button>`;right=badPreview(d);}
 if(n===2){const chosen=demoState.choice;left=`<div class="eyebrow">暂停一下 · 你来判断</div><h2>${d.question}</h2><div class="quiz-options">${d.options.map((x,i)=>`<button class="quiz-option ${chosen===i?'chosen':''}" data-demo-choice="${i}" aria-pressed="${chosen===i}">${String.fromCharCode(65+i)}. ${x}</button>`).join('')}</div><div class="feedback ${chosen===d.correct?'correct':'incorrect'}" role="status">${chosen===null?'':chosen===d.correct?'找到了。'+esc(d.reason):'这个修改没有解决最关键的问题。再对照原始材料想一想。'}</div><details><summary>回看原始材料</summary>${plainLines(d.material.lines)}</details>${chosen===d.correct?'<button class="btn" data-demo-next>看具体怎样追问修改</button>':''}`;right=badPreview(d);}
 if(n===3){left=`<div class="eyebrow">第二轮 · 具体修改</div><h2>说出问题，也说清怎么改。</h2>${conversation('你',d.revision)}${conversation('AI 示例',d.response)}<div class="version-switch" role="group" aria-label="比较修改前后"><button class="pill ${demoState.version==='initial'?'selected':''}" data-demo-version="initial" aria-pressed="${demoState.version==='initial'}">对照初稿</button><button class="pill ${demoState.version==='final'?'selected':''}" data-demo-version="final" aria-pressed="${demoState.version==='final'}">看修改结果</button></div><button class="btn" data-demo-next>看看最后的效果</button>`;right=demoState.version==='initial'?badPreview(d):`<div class="workspace-caption">第二轮结果 / ${d.format==='PPT'?'浏览器课件预览':'示例成品'}</div><div id="artifact-body">${finalArtifact(d)}</div>`;}
 if(n===4){left=`<div class="eyebrow">最后一步 · 自己试一试</div><h2>我们来检查一下，是否做到了要求。</h2><p>${esc(d.takeaway)}</p><div class="checklist">${d.checks.map(x=>`<label><input type="checkbox" data-demo-accept>${esc(x)}</label>`).join('')}</div><p class="small-note" id="demo-accept-count" role="status">已检查 0 / ${d.checks.length} 项</p><button class="btn secondary" data-export-demo>保存完整示例 HTML</button><p class="small-note">这里保存的是可以用浏览器打开的示例。需要 PPT 或 Word 文件时，再请你使用的 AI 生成 .pptx 或 .docx，并打开检查。</p><details><summary>轮到我了：怎样换成自己的材料？</summary><p>准备自己的材料，模仿这次提问、核查和修改过程。没有的信息请 AI 反问，正式交付前实际打开文件。</p>${template(d.ask+'\n请只基于我接下来提供的真实材料：缺信息先问，先给小样让我检查。\n'+d.revision)}</details>`;right=`<div class="workspace-caption">最终示例 / ${d.result.type==='slides'?'可以翻页、查看讲者备注':d.result.type==='checklist'?'可以勾选':d.result.type==='board'?'可以改变任务状态':d.result.type==='evidence'?'可以点依据回看原文':'逐项检查内容与排版'}</div><div id="artifact-body">${finalArtifact(d)}</div>`;}
 if(n===4)left+=`<a class="trust-highlight-link" href="#trust">还想多检查一遍？看看怎样请另一个 AI 帮忙，以及有不同意见时怎么办。</a>`;
 $('#demo-stage').innerHTML=`<div class="walkthrough-layout"><section class="walkthrough-story">${left}<div class="in-context-help"><strong>这里没听懂？看一次追问示范</strong><button class="quiet" data-demo-help aria-expanded="${demoState.showHelp}">${esc(d.helpQ)}</button>${demoState.showHelp?conversation('你',d.helpQ)+conversation('AI 示例',d.helpA):''}</div></section><section class="walkthrough-workspace" aria-label="案例材料和成品">${right}</section></div><div class="demo-bottom"><button class="btn secondary" data-demo-prev ${n===0?'disabled':''}>上一步</button><span>第 ${n+1} / 5 步</span>${n<4?`<button class="btn" data-demo-next ${n===2&&demoState.choice!==d.correct?'disabled':''}>${n===2?'先选择正确的修改方向':'下一步'}</button>`:button('换一个案例练练','#scenes')}</div>`;
}
function badPreview(d){return `<div class="workspace-caption">第一轮结果 / 故意保留错误，供你检查</div><article class="paper-preview bad-draft"><div class="draft-ribbon">未验收初稿</div><h2>${esc(d.bad.title)}</h2>${plainLines(d.bad.lines)}</article>`;}
function demoMove(n){demoState.step=Math.max(0,Math.min(4,n));demoState.slide=0;demoState.version='final';demoState.showHelp=false;showDemoStep();const target=$('#demo-stage');target.setAttribute('tabindex','-1');target.focus({preventScroll:true});if(target.getBoundingClientRect().top<0)target.scrollIntoView({block:'start',behavior:'smooth'});}
function exportDemo(d){const content=`<h1>${esc(d.title)}</h1><p>AI 生活课堂 · 人工编写的虚构教学样例 · 静态阅读版</p><h2>原始材料</h2>${plainLines(d.material.lines)}<h2>初稿</h2>${plainLines(d.bad.lines)}<h2>发现的问题</h2><p>${esc(d.reason)}</p><h2>修改要求</h2><p>${esc(d.revision)}</p><h2>修改后的示例</h2>${finalArtifact(d,true)}<h2>验收要点</h2>${plainLines(d.checks)}<p>不是真实研究、财务资料、活动通知、简历或学术论文。请勿冒用。</p>`;const html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(d.title)} · 教学样例</title><style>body{font:18px/1.8 system-ui,'Microsoft YaHei',sans-serif;color:#202c45;max-width:920px;margin:40px auto;padding:24px}h1,h2,h3{line-height:1.5}table{border-collapse:collapse;width:100%}td,th{border:1px solid #cbd5e1;padding:12px;text-align:left}.slide-canvas{background:#eaf0ff;border-radius:18px;padding:35px;margin:24px 0;break-inside:avoid}.slide-footer{display:flex;justify-content:space-between;font-size:14px}.slide-kicker,.paper-masthead{color:#2e59d9;font-size:14px}.paper-preview{padding:30px;border:1px solid #dce3ed}.bar-track{height:20px;background:#edf2fc}.bar-track span{display:block;height:100%;background:#2e59d9}.report-bar{margin:16px 0}.report-bar>div:first-child{display:flex;justify-content:space-between}.live-checklist label{display:block;padding:12px}.task-board article,.evidence-cards>div{border:1px solid #dce3ed;padding:20px;margin:12px 0}.export-note{color:#52627b;margin-bottom:30px}@media(max-width:600px){body{padding:12px;margin:0}.table-scroll{overflow:auto}.paper-preview{padding:14px}}@media print{body{font-size:12pt}.slide-canvas{break-inside:avoid}}</style><body>${content}</body></html>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`教学示例-${d.slug}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('已准备静态示例文件，可离线阅读或打印。');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.demoFilter!==undefined){demoAudience=b.dataset.demoFilter;$$('[data-demo-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});updateDemos();}
 const d=DEMOS.find(x=>x.slug===demoState.slug);if(!d||!$('#demo-stage'))return;
 if(b.dataset.demoStep!==undefined)demoMove(Number(b.dataset.demoStep));
 if(b.hasAttribute('data-demo-next'))demoMove(demoState.step+1);
 if(b.hasAttribute('data-demo-prev'))demoMove(demoState.step-1);
 if(b.dataset.demoChoice!==undefined){demoState.choice=Number(b.dataset.demoChoice);showDemoStep();$('#demo-stage .feedback').setAttribute('tabindex','-1');$('#demo-stage .feedback').focus({preventScroll:true});}
 if(b.dataset.demoVersion!==undefined){demoState.version=b.dataset.demoVersion;demoState.slide=0;showDemoStep();}
 if(b.hasAttribute('data-demo-help')){demoState.showHelp=!demoState.showHelp;const target=$('.in-context-help');b.setAttribute('aria-expanded',String(demoState.showHelp));$$('.walk-message',target).forEach(x=>x.remove());if(demoState.showHelp)target.insertAdjacentHTML('beforeend',conversation('你',d.helpQ)+conversation('AI 示例',d.helpA));}
 if(b.dataset.slideMove!==undefined){demoState.slide=Math.max(0,Math.min(d.result.slides.length-1,demoState.slide+Number(b.dataset.slideMove)));$('#artifact-body').innerHTML=finalArtifact(d);}
 if(b.dataset.sourceLine!==undefined){$('#source-excerpt').textContent=d.material.lines[Number(b.dataset.sourceLine)];}
 if(b.hasAttribute('data-export-demo'))exportDemo(d);
});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-case-check'))$('#case-check-count').textContent=`已准备 ${$$('[data-case-check]:checked').length} / ${$$('[data-case-check]').length} 件`;
 if(e.target.hasAttribute('data-demo-accept'))$('#demo-accept-count').textContent=`已检查 ${$$('[data-demo-accept]:checked').length} / ${$$('[data-demo-accept]').length} 项`;
 if(e.target.hasAttribute('data-task-status'))$('#board-count').textContent=`已完成 ${$$('[data-task-status]').filter(x=>x.value==='已完成').length} / 4 项 · 本地模拟，不会通知组员`;
});
